CommitDate: Thu May 22 17:12:47 2025 +0100

    Bug 1967835 - Do not ask for removal of unavailable newsgroup. r=mkmelin


    Replace the intrusive auto-unsubscribe dialog with a simple status message, displayed in the same way as for groups without new messages.

    Differential Revision: https://phabricator.services.mozilla.com/D250614

diff --git a/mail/locales/en-US/chrome/messenger/news.properties b/mail/locales/en-US/chrome/messenger/news.properties
index 92080cbafca..93f4a321d9a 100644
--- a/mail/locales/en-US/chrome/messenger/news.properties
+++ b/mail/locales/en-US/chrome/messenger/news.properties
@@ -14,8 +14,5 @@ enterUserPassServer=Please enter a username and password for %S:
 # the password for; %2$S is the server from which the newsgroup is accessed
 enterUserPassGroup=Please enter a username and password for %1$S on %2$S:

-# LOCALIZATION NOTE (autoUnsubscribeText): %1$S is the newsgroup and %2$S is the newsgroup-server it is being removed from.
-autoUnsubscribeText=The newsgroup %1$S does not appear to exist on the host %2$S.  Would you like to unsubscribe from it?
-
 # LOCALIZATION NOTE (autoSubscribeText): %1$S is the newsgroup.
 autoSubscribeText=Would you like to subscribe to %1$S?
diff --git a/mail/locales/en-US/messenger/news.ftl b/mail/locales/en-US/messenger/news.ftl
index 4b75a5f0121..e2a521dacbd 100644
--- a/mail/locales/en-US/messenger/news.ftl
+++ b/mail/locales/en-US/messenger/news.ftl
@@ -28,3 +28,7 @@ downloading-articles-for-offline =
 # $newsgroup (String) - The name of the newsgroup.
 no-articles-to-download =
     There are no articles to download for { $newsgroup }.
+
+# Variables:
+# $newsgroup (String) - The name of the newsgroup.
+no-such-newsgroup = The newsgroup { $newsgroup } is not available on the server.
diff --git a/mailnews/news/public/nsINntpIncomingServer.idl b/mailnews/news/public/nsINntpIncomingServer.idl
index e286f99e22d..309a67932c7 100644
--- a/mailnews/news/public/nsINntpIncomingServer.idl
+++ b/mailnews/news/public/nsINntpIncomingServer.idl
@@ -94,13 +94,4 @@ interface nsINntpIncomingServer : nsISupports {
      *       is subscribed to (e.g., by containsNewsgroup)
      */
     nsIMsgNewsFolder findGroup(in AUTF8String name);
-
-    /**
-     * After prompting the user for confirmation, unsubscribe from a newsgroup
-     * that is not available on the server.
-     *
-     * @param group The name of the news folder.
-     * @return true if the group has been removed.
-     */
-    boolean removeUnavailableGroup(in AUTF8String name);
 };
diff --git a/mailnews/news/src/NntpClient.sys.mjs b/mailnews/news/src/NntpClient.sys.mjs
index 022262d0305..cac8f2b3db5 100644
--- a/mailnews/news/src/NntpClient.sys.mjs
+++ b/mailnews/news/src/NntpClient.sys.mjs
@@ -185,9 +185,9 @@ export class NntpClient {
         this._actionError(res.status, res.statusText);
         return;
       case NO_SUCH_NEWSGROUP:
-        if (this._server.removeUnavailableGroup(this._newsFolder.name)) {
-          this._newsGroup = null;
-        }
+        this._updateStatus("no-such-newsgroup", {
+          newsgroup: this._newsFolder.prettyName,
+        });
         // Close the connection without any further error message.
         this._actionDone(Cr.NS_ERROR_FAILURE);
         return;
